package com.enchanttracker;

import lombok.Getter;
import lombok.Setter;

/**
 * Tracks a single enchanting run: the spell being cast, the item being consumed
 * and how many of that item remain in the inventory.
 */
@Getter
@Setter
class EnchantSession
{
	enum State
	{
		/** Spell selected, waiting to see which item starts decreasing. */
		ARMED,
		/** Item identified, actively counting down. */
		ACTIVE,
		/** Remaining hit zero via enchanting. */
		FINISHED,
		/** Items remain but no progress within the timeout. */
		STALLED,
		/** Session abandoned (banked, logged out, different activity). */
		CANCELLED
	}

	private final EnchantSpell spell;
	private State state = State.ARMED;
	/** Item id being enchanted, or -1 until identified. */
	private int targetItemId = -1;
	private int remaining;
	/** Game tick at which the remaining count last decreased. */
	private int lastProgressTick;
	/** Game tick at which the session entered a terminal state. */
	private int endTick;
	/**
	 * Tick at which the target item ran out while other enchantable items of the
	 * same spell remained, or -1. Jewellery enchants can roll over to the next
	 * item type, so finishing is deferred briefly to see if that happens.
	 */
	private int pendingFinishTick = -1;

	EnchantSession(EnchantSpell spell, int tick)
	{
		this.spell = spell;
		this.lastProgressTick = tick;
	}

	boolean isLocked()
	{
		return targetItemId != -1;
	}

	boolean isRunning()
	{
		return state == State.ARMED || state == State.ACTIVE;
	}

	boolean isVisible()
	{
		return isRunning() || state == State.FINISHED || state == State.STALLED;
	}

	void lock(int itemId, int tick)
	{
		targetItemId = itemId;
		state = State.ACTIVE;
		lastProgressTick = tick;
		pendingFinishTick = -1;
	}

	void end(State terminal, int tick)
	{
		state = terminal;
		endTick = tick;
	}

	int estimateTicksRemaining()
	{
		int casts = (remaining + spell.getItemsPerCast() - 1) / spell.getItemsPerCast();
		return casts * spell.getTicksPerCast();
	}
}

package com.enchanttracker;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;

/**
 * Enchantment spells that consume items from the inventory, together with the
 * unenchanted items each spell accepts as input.
 */
@Getter
@RequiredArgsConstructor
public enum EnchantSpell
{
	LVL_1("Lvl-1 Enchant", InterfaceID.MagicSpellbook.ENCHANT_1, 1, 7, ImmutableSet.of(
		ItemID.SAPPHIRE_RING,
		ItemID.SAPPHIRE_NECKLACE,
		ItemID.JEWL_SAPPHIRE_BRACELET,
		ItemID.STRUNG_SAPPHIRE_AMULET,
		ItemID.OPAL_RING,
		ItemID.OPAL_NECKLACE,
		ItemID.OPAL_BRACELET,
		ItemID.STRUNG_OPAL_AMULET
	)),
	LVL_2("Lvl-2 Enchant", InterfaceID.MagicSpellbook.ENCHANT_2, 1, 7, ImmutableSet.of(
		ItemID.EMERALD_RING,
		ItemID.EMERALD_NECKLACE,
		ItemID.JEWL_EMERALD_BRACELET,
		ItemID.STRUNG_EMERALD_AMULET,
		ItemID.JADE_RING,
		ItemID.JADE_NECKLACE,
		ItemID.JADE_BRACELET,
		ItemID.STRUNG_JADE_AMULET,
		ItemID.NATURE_AMULET // Pre-nature amulet
	)),
	LVL_3("Lvl-3 Enchant", InterfaceID.MagicSpellbook.ENCHANT_3, 1, 7, ImmutableSet.of(
		ItemID.RUBY_RING,
		ItemID.RUBY_NECKLACE,
		ItemID.JEWL_RUBY_BRACELET,
		ItemID.STRUNG_RUBY_AMULET,
		ItemID.TOPAZ_RING,
		ItemID.TOPAZ_NECKLACE,
		ItemID.TOPAZ_BRACELET,
		ItemID.STRUNG_TOPAZ_AMULET
	)),
	LVL_4("Lvl-4 Enchant", InterfaceID.MagicSpellbook.ENCHANT_4, 1, 7, ImmutableSet.of(
		ItemID.DIAMOND_RING,
		ItemID.DIAMOND_NECKLACE,
		ItemID.JEWL_DIAMOND_BRACELET,
		ItemID.STRUNG_DIAMOND_AMULET
	)),
	LVL_5("Lvl-5 Enchant", InterfaceID.MagicSpellbook.ENCHANT_5, 1, 7, ImmutableSet.of(
		ItemID.DRAGONSTONE_RING,
		ItemID.DRAGONSTONE_NECKLACE,
		ItemID.JEWL_DRAGONSTONE_BRACELET,
		ItemID.STRUNG_DRAGONSTONE_AMULET
	)),
	LVL_6("Lvl-6 Enchant", InterfaceID.MagicSpellbook.ENCHANT_6, 1, 7, ImmutableSet.of(
		ItemID.ONYX_RING,
		ItemID.ONYX_NECKLACE,
		ItemID.JEWL_ONYX_BRACELET,
		ItemID.STRUNG_ONYX_AMULET
	)),
	LVL_7("Lvl-7 Enchant", InterfaceID.MagicSpellbook.ENCHANT_7, 1, 7, ImmutableSet.of(
		ItemID.ZENYTE_RING,
		ItemID.ZENYTE_NECKLACE,
		ItemID.ZENYTE_BRACELET,
		ItemID.ZENYTE_AMULET
	)),
	CROSSBOW_BOLT("Enchant Crossbow Bolt", InterfaceID.MagicSpellbook.XBOWS_ENCHANT, 10, 3, ImmutableSet.of(
		ItemID.OPAL_BOLT,
		ItemID.PEARL_BOLT,
		ItemID.XBOWS_CROSSBOW_BOLTS_BLURITE_TIPPED_JADE,
		ItemID.XBOWS_CROSSBOW_BOLTS_STEEL_TIPPED_REDTOPAZ,
		ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL_TIPPED_SAPPHIRE,
		ItemID.XBOWS_CROSSBOW_BOLTS_MITHRIL_TIPPED_EMERALD,
		ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_TIPPED_RUBY,
		ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_TIPPED_DIAMOND,
		ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_TIPPED_DRAGONSTONE,
		ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_TIPPED_ONYX,
		ItemID.DRAGON_BOLTS_UNENCHANTED_OPAL,
		ItemID.DRAGON_BOLTS_UNENCHANTED_JADE,
		ItemID.DRAGON_BOLTS_UNENCHANTED_PEARL,
		ItemID.DRAGON_BOLTS_UNENCHANTED_TOPAZ,
		ItemID.DRAGON_BOLTS_UNENCHANTED_SAPPHIRE,
		ItemID.DRAGON_BOLTS_UNENCHANTED_EMERALD,
		ItemID.DRAGON_BOLTS_UNENCHANTED_RUBY,
		ItemID.DRAGON_BOLTS_UNENCHANTED_DIAMOND,
		ItemID.DRAGON_BOLTS_UNENCHANTED_DRAGONSTONE,
		ItemID.DRAGON_BOLTS_UNENCHANTED_ONYX
	));

	private static final Pattern JEWELLERY_SPELL_PATTERN = Pattern.compile("Lvl-([1-7]) Enchant");

	/** Human readable spell name, as it appears in the spellbook. */
	private final String spellName;
	/** Component id of the spell widget in the standard spellbook. */
	private final int spellWidgetId;
	/** Number of input items consumed per cast. */
	private final int itemsPerCast;
	/** Game ticks between casts when the spell auto-repeats. */
	private final int ticksPerCast;
	/** Unenchanted item ids this spell accepts. */
	private final Set<Integer> inputItems;

	public boolean accepts(int itemId)
	{
		return inputItems.contains(itemId);
	}

	/**
	 * Resolve a spell from its spellbook widget component id.
	 */
	public static EnchantSpell fromSpellWidget(int widgetId)
	{
		for (EnchantSpell spell : values())
		{
			if (spell.spellWidgetId == widgetId)
			{
				return spell;
			}
		}
		return null;
	}

	/**
	 * Resolve a spell from menu text, e.g. the target of a "Cast" menu entry
	 * once colour tags have been stripped.
	 */
	public static EnchantSpell fromMenuText(String text)
	{
		if (text == null)
		{
			return null;
		}

		Matcher m = JEWELLERY_SPELL_PATTERN.matcher(text);
		if (m.find())
		{
			return values()[Integer.parseInt(m.group(1)) - 1];
		}

		if (text.contains(CROSSBOW_BOLT.spellName))
		{
			return CROSSBOW_BOLT;
		}

		return null;
	}

	/**
	 * Resolve the spell that accepts the given item, if any.
	 */
	public static EnchantSpell forItem(int itemId)
	{
		for (EnchantSpell spell : values())
		{
			if (spell.accepts(itemId))
			{
				return spell;
			}
		}
		return null;
	}
}

package com.enchanttracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(EnchantTrackerConfig.GROUP)
public interface EnchantTrackerConfig extends Config
{
	String GROUP = "enchanttracker";

	@ConfigSection(
		name = "Notifications",
		description = "When to send notifications",
		position = 0
	)
	String notificationSection = "notifications";

	@ConfigSection(
		name = "Overlay",
		description = "Overlay display options",
		position = 1
	)
	String overlaySection = "overlay";

	@ConfigItem(
		keyName = "notifyFinished",
		name = "Notify when finished",
		description = "Send a notification when there are no enchantable items left in your inventory",
		section = notificationSection,
		position = 0
	)
	default Notification notifyFinished()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "notifyStalled",
		name = "Notify when interrupted",
		description = "Send a notification if enchanting stops while enchantable items remain (e.g. out of runes, moved, or level-up)",
		section = notificationSection,
		position = 1
	)
	default Notification notifyStalled()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "stallTimeout",
		name = "Interrupt timeout",
		description = "Seconds without progress before enchanting is considered interrupted",
		section = notificationSection,
		position = 2
	)
	@Units(Units.SECONDS)
	@Range(min = 5, max = 120)
	default int stallTimeout()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Show an overlay with the number of enchantable items remaining while enchanting",
		section = overlaySection,
		position = 0
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showEta",
		name = "Show time remaining",
		description = "Show an estimate of how long the remaining items will take to enchant",
		section = overlaySection,
		position = 1
	)
	default boolean showEta()
	{
		return true;
	}

	@ConfigItem(
		keyName = "finishedOverlayDuration",
		name = "Finished message duration",
		description = "How long the overlay stays visible after enchanting finishes",
		section = overlaySection,
		position = 2
	)
	@Units(Units.SECONDS)
	@Range(min = 0, max = 60)
	default int finishedOverlayDuration()
	{
		return 5;
	}
}

package com.enchanttracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class EnchantTrackerOverlay extends OverlayPanel
{
	private final EnchantTrackerPlugin plugin;
	private final EnchantTrackerConfig config;

	@Inject
	EnchantTrackerOverlay(EnchantTrackerPlugin plugin, EnchantTrackerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		EnchantSession session = plugin.getSession();
		if (session == null || !session.isVisible())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(session.getSpell().getSpellName())
			.color(session.getState() == EnchantSession.State.FINISHED ? Color.GREEN
				: session.getState() == EnchantSession.State.STALLED ? Color.ORANGE
				: Color.WHITE)
			.build());

		switch (session.getState())
		{
			case FINISHED:
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Enchanting finished")
					.leftColor(Color.GREEN)
					.build());
				break;
			case STALLED:
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Interrupted")
					.leftColor(Color.ORANGE)
					.right(Integer.toString(session.getRemaining()))
					.build());
				break;
			default:
				String itemName = plugin.getTargetItemName();
				panelComponent.getChildren().add(LineComponent.builder()
					.left(itemName != null ? itemName : "Remaining")
					.right(Integer.toString(session.getRemaining()))
					.build());

				if (config.showEta() && session.isLocked())
				{
					panelComponent.getChildren().add(LineComponent.builder()
						.left("Time left")
						.right(formatEta(session.estimateTicksRemaining()))
						.build());
				}
				break;
		}

		return super.render(graphics);
	}

	private static String formatEta(int ticks)
	{
		int seconds = (int) Math.ceil(ticks * 0.6);
		int minutes = seconds / 60;
		seconds %= 60;
		return minutes > 0 ? String.format("%d:%02d", minutes, seconds) : seconds + "s";
	}
}

package com.enchanttracker;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Enchant Tracker",
	description = "Shows how many enchantable items remain and notifies you when enchanting finishes",
	tags = {"enchant", "magic", "jewellery", "bolts", "notification", "afk"}
)
public class EnchantTrackerPlugin extends Plugin
{
	/** Give up waiting for the first item to be consumed after this many ticks. */
	private static final int ARM_TIMEOUT_TICKS = 100;

	@Inject
	private Client client;

	@Inject
	private EnchantTrackerConfig config;

	@Inject
	private Notifier notifier;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private EnchantTrackerOverlay overlay;

	@Getter
	private EnchantSession session;

	/** Snapshot of enchantable input item counts, used to detect which item is being consumed. */
	private final Map<Integer, Integer> lastCounts = new HashMap<>();

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		session = null;
		lastCounts.clear();
	}

	@Provides
	EnchantTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EnchantTrackerConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			session = null;
			lastCounts.clear();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		MenuAction action = event.getMenuAction();

		if (action == MenuAction.WIDGET_TARGET_ON_WIDGET)
		{
			// Spell cast directly on an inventory item (jewellery enchants)
			EnchantSpell spell = null;
			Widget selected = client.getSelectedWidget();
			if (selected != null)
			{
				spell = EnchantSpell.fromSpellWidget(selected.getId());
			}
			if (spell == null)
			{
				spell = EnchantSpell.fromMenuText(Text.removeTags(event.getMenuTarget()));
			}
			if (spell == null)
			{
				return;
			}

			int itemId = event.getItemId();
			if (itemId <= 0)
			{
				Widget target = event.getWidget();
				if (target != null)
				{
					itemId = target.getItemId();
				}
			}

			startSession(spell, spell.accepts(itemId) ? itemId : -1);
		}
		else if (action == MenuAction.CC_OP || action == MenuAction.WIDGET_TARGET)
		{
			// Spell clicked in the spellbook. Enchant Crossbow Bolt opens an
			// interface, so we won't know which bolt is used until it starts
			// being consumed.
			Widget widget = event.getWidget();
			if (widget == null)
			{
				return;
			}

			EnchantSpell spell = EnchantSpell.fromSpellWidget(widget.getId());
			if (spell == EnchantSpell.CROSSBOW_BOLT && "Cast".equalsIgnoreCase(Text.removeTags(event.getMenuOption())))
			{
				startSession(spell, -1);
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		ItemContainer inventory = event.getItemContainer();
		if (session == null || !session.isRunning())
		{
			snapshotCounts(inventory);
			return;
		}

		EnchantSpell spell = session.getSpell();
		int tick = client.getTickCount();

		// Lock onto (or follow) whichever accepted item is being consumed. The game
		// enchants the first matching jewellery in the inventory, so the consumed
		// item can differ from the one the spell was cast on.
		int currentTarget = session.getTargetItemId();
		boolean targetDecreased = currentTarget != -1
			&& inventory.count(currentTarget) < lastCounts.getOrDefault(currentTarget, 0);
		if (!targetDecreased)
		{
			for (int itemId : spell.getInputItems())
			{
				int before = lastCounts.getOrDefault(itemId, 0);
				int now = inventory.count(itemId);
				if (now < before)
				{
					session.lock(itemId, tick);
					log.debug("Locked enchant target {} ({} -> {})", itemId, before, now);
					break;
				}
			}
		}

		int previous = session.getRemaining();
		int remaining = session.isLocked()
			? inventory.count(session.getTargetItemId())
			: countAll(inventory, spell);
		session.setRemaining(remaining);

		if (remaining < previous)
		{
			session.setLastProgressTick(tick);
		}

		if (session.isLocked() && remaining == 0 && previous > 0)
		{
			// Distinguish "enchanted the last one" from "banked / dropped the stack":
			// a genuine final cast removes at most one batch.
			if (previous > spell.getItemsPerCast() || isBankOpen())
			{
				session.end(EnchantSession.State.CANCELLED, tick);
			}
			else if (countAll(inventory, spell) > 0)
			{
				// Other enchantable items remain; wait a couple of casts to see
				// whether the game rolls over to them before declaring done.
				session.setPendingFinishTick(tick);
			}
			else
			{
				finish();
			}
		}

		snapshotCounts(inventory);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (session == null)
		{
			return;
		}

		int tick = client.getTickCount();
		int sinceProgress = tick - session.getLastProgressTick();

		switch (session.getState())
		{
			case ARMED:
				if (sinceProgress > ARM_TIMEOUT_TICKS)
				{
					session.end(EnchantSession.State.CANCELLED, tick);
				}
				break;
			case ACTIVE:
				if (session.getPendingFinishTick() != -1
					&& tick - session.getPendingFinishTick() > 2 * session.getSpell().getTicksPerCast())
				{
					finish();
				}
				else if (session.getRemaining() > 0 && sinceProgress > stallTimeoutTicks())
				{
					session.end(EnchantSession.State.STALLED, tick);
					String name = getTargetItemName();
					notifier.notify(config.notifyStalled(), String.format(
						"Enchanting interrupted with %d %s remaining",
						session.getRemaining(), name != null ? pluralise(name, session.getRemaining()) : "items"));
				}
				break;
			case FINISHED:
			case STALLED:
				if (tick - session.getEndTick() > secondsToTicks(config.finishedOverlayDuration()))
				{
					session = null;
				}
				break;
			default:
				session = null;
				break;
		}
	}

	private void startSession(EnchantSpell spell, int itemId)
	{
		int tick = client.getTickCount();
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);

		if (session != null && session.isRunning() && session.getSpell() == spell
			&& (itemId == -1 || session.getTargetItemId() == itemId))
		{
			// Manual re-cast of the same spell; keep counting.
			session.setLastProgressTick(tick);
			return;
		}

		session = new EnchantSession(spell, tick);
		if (itemId != -1)
		{
			session.lock(itemId, tick);
		}

		if (inventory != null)
		{
			session.setRemaining(itemId != -1 ? inventory.count(itemId) : countAll(inventory, spell));
			snapshotCounts(inventory);
		}

		log.debug("Started enchant session for {} (item {})", spell, itemId);
	}

	private void finish()
	{
		session.end(EnchantSession.State.FINISHED, client.getTickCount());
		String name = getTargetItemName();
		notifier.notify(config.notifyFinished(), String.format(
			"Enchanting finished: no %s left", name != null ? pluralise(name, 2).toLowerCase() : "enchantable items"));
	}

	private void snapshotCounts(ItemContainer inventory)
	{
		lastCounts.clear();
		if (inventory == null)
		{
			return;
		}
		for (EnchantSpell spell : EnchantSpell.values())
		{
			for (int itemId : spell.getInputItems())
			{
				int count = inventory.count(itemId);
				if (count > 0)
				{
					lastCounts.put(itemId, count);
				}
			}
		}
	}

	private static int countAll(ItemContainer inventory, EnchantSpell spell)
	{
		int total = 0;
		for (int itemId : spell.getInputItems())
		{
			total += inventory.count(itemId);
		}
		return total;
	}

	private boolean isBankOpen()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		return bank != null && !bank.isHidden();
	}

	private int stallTimeoutTicks()
	{
		return secondsToTicks(config.stallTimeout());
	}

	private static int secondsToTicks(int seconds)
	{
		return (int) Math.ceil(seconds / 0.6);
	}

	private static String pluralise(String name, int count)
	{
		if (count == 1 || name.endsWith("s"))
		{
			return name;
		}
		return name + "s";
	}

	String getTargetItemName()
	{
		if (session == null || !session.isLocked())
		{
			return null;
		}
		return itemManager.getItemComposition(session.getTargetItemId()).getName();
	}
}

package com.enchanttracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class EnchantSpellTest
{
	@Test
	public void resolvesJewellerySpellsFromMenuText()
	{
		assertEquals(EnchantSpell.LVL_1, EnchantSpell.fromMenuText("Lvl-1 Enchant -> Sapphire ring"));
		assertEquals(EnchantSpell.LVL_5, EnchantSpell.fromMenuText("Lvl-5 Enchant -> Dragonstone amulet"));
		assertEquals(EnchantSpell.LVL_7, EnchantSpell.fromMenuText("Lvl-7 Enchant -> Zenyte ring"));
	}

	@Test
	public void resolvesBoltSpellFromMenuText()
	{
		assertEquals(EnchantSpell.CROSSBOW_BOLT, EnchantSpell.fromMenuText("Enchant Crossbow Bolt"));
	}

	@Test
	public void ignoresUnrelatedMenuText()
	{
		assertNull(EnchantSpell.fromMenuText("High Level Alchemy -> Rune platebody"));
		assertNull(EnchantSpell.fromMenuText(null));
	}

	@Test
	public void resolvesSpellsFromWidgetIds()
	{
		assertEquals(EnchantSpell.LVL_1, EnchantSpell.fromSpellWidget(InterfaceID.MagicSpellbook.ENCHANT_1));
		assertEquals(EnchantSpell.LVL_6, EnchantSpell.fromSpellWidget(InterfaceID.MagicSpellbook.ENCHANT_6));
		assertEquals(EnchantSpell.CROSSBOW_BOLT, EnchantSpell.fromSpellWidget(InterfaceID.MagicSpellbook.XBOWS_ENCHANT));
		assertNull(EnchantSpell.fromSpellWidget(InterfaceID.MagicSpellbook.WIND_BOLT));
	}

	@Test
	public void resolvesSpellForItem()
	{
		assertEquals(EnchantSpell.LVL_1, EnchantSpell.forItem(ItemID.SAPPHIRE_RING));
		assertEquals(EnchantSpell.LVL_2, EnchantSpell.forItem(ItemID.NATURE_AMULET));
		assertEquals(EnchantSpell.LVL_4, EnchantSpell.forItem(ItemID.STRUNG_DIAMOND_AMULET));
		assertEquals(EnchantSpell.CROSSBOW_BOLT, EnchantSpell.forItem(ItemID.DRAGON_BOLTS_UNENCHANTED_RUBY));
		assertNull(EnchantSpell.forItem(ItemID.COINS));
	}

	@Test
	public void inputItemsAreUniqueAcrossSpells()
	{
		Set<Integer> seen = new HashSet<>();
		for (EnchantSpell spell : EnchantSpell.values())
		{
			for (int itemId : spell.getInputItems())
			{
				assertTrue("Item " + itemId + " listed for more than one spell", seen.add(itemId));
			}
		}
	}
}

